import { Sparkles } from 'lucide-react'

/**
 * Follow-up suggestions are simple templates built from the question and the sources.
 * They are not generated by Gemini, so they cost nothing and never fail.
 */
export function followUpSuggestions(question, sources = []) {
  const suggestions = []
  const file = sources[0] && sources[0].filename
  if (file) suggestions.push(`Summarize the key points of ${file}`)
  suggestions.push('Can you give a simple example of this?')
  suggestions.push('What are the most important terms in this answer?')
  return suggestions.slice(0, 3)
}

export default function FollowUps({ suggestions, onSelect, disabled = false }) {
  if (!suggestions || suggestions.length === 0) return null
  return (
    <div className="animate-fade-up pl-11" aria-label="Follow-up questions">
      <p className="mb-2 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-slate-500">
        <Sparkles size={12} aria-hidden="true" /> You could ask next
      </p>
      <div className="flex flex-wrap gap-2">
        {suggestions.map((text) => (
          <button
            key={text}
            type="button"
            onClick={() => onSelect(text)}
            disabled={disabled}
            className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-left text-sm text-slate-700 transition hover:border-indigo-300 hover:text-indigo-700 disabled:opacity-50"
          >
            {text}
          </button>
        ))}
      </div>
    </div>
  )
}
